-- BOLU (Blue Ocean Life Utility) - Smart KJA OWC Database Schema & Seed Data
CREATE DATABASE IF NOT EXISTS `smart_kja_owc` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `smart_kja_owc";

CREATE TABLE IF NOT EXISTS `users` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `username` VARCHAR(50) NOT NULL UNIQUE,
  `email` VARCHAR(120) NOT NULL UNIQUE,
  `password_hash` VARCHAR(255) NOT NULL,
  `full_name` VARCHAR(120) NOT NULL,
  `role` ENUM('admin','operator','viewer') NOT NULL DEFAULT 'viewer',
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `last_login` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `devices` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `device_code` VARCHAR(32) NOT NULL UNIQUE,
  `device_name` VARCHAR(120) NOT NULL,
  `device_type` ENUM('owc','wave_sensor','water_sensor','camera','gateway') NOT NULL,
  `status` ENUM('online','offline','maintenance') NOT NULL DEFAULT 'offline',
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `api_token` CHAR(64) NULL,
  `last_communication` DATETIME NULL,
  `calibration_status` ENUM('calibrated','due','overdue','none') NOT NULL DEFAULT 'none',
  `calibration_date` DATE NULL,
  `notes` TEXT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `device_locations` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `device_id` INT NOT NULL,
  `latitude` DECIMAL(10,7) NOT NULL,
  `longitude` DECIMAL(10,7) NOT NULL,
  `location_name` VARCHAR(150) NULL,
  `installed_at` DATE NULL,
  `notes` TEXT NULL,
  `updated_at` DATETIME NULL,
  FOREIGN KEY (`device_id`) REFERENCES `devices`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `thresholds` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `parameter` VARCHAR(40) NOT NULL,
  `species` VARCHAR(60) NOT NULL DEFAULT 'Umum',
  `min_value` DECIMAL(10,3) NULL,
  `max_value` DECIMAL(10,3) NULL,
  `warn_span` DECIMAL(10,3) NULL,
  `unit` VARCHAR(20) NULL,
  `updated_by` INT NULL,
  `updated_at` DATETIME NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `system_settings` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `setting_key` VARCHAR(80) NOT NULL UNIQUE,
  `setting_value` TEXT NULL,
  `description` VARCHAR(255) NULL,
  `updated_at` DATETIME NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `fish_species` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `name` VARCHAR(100) NOT NULL,
  `latin_name` VARCHAR(120) NULL,
  `category` ENUM('laut','tawar','brackish') NOT NULL DEFAULT 'laut',
  `cycle_months_min` INT NULL,
  `cycle_months_max` INT NULL,
  `target_weight_kg` DECIMAL(8,3) NULL,
  `lw_a` DECIMAL(10,5) NOT NULL DEFAULT 0.01060,
  `lw_b` DECIMAL(6,3) NOT NULL DEFAULT 3.050,
  `optimal_temp_min` DECIMAL(5,1) NULL,
  `optimal_temp_max` DECIMAL(5,1) NULL,
  `optimal_ph_min` DECIMAL(4,1) NULL,
  `optimal_ph_max` DECIMAL(4,1) NULL,
  `optimal_salinity_min` DECIMAL(6,2) NULL,
  `optimal_salinity_max` DECIMAL(6,2) NULL,
  `description` TEXT NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `kja_sites` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `slug` VARCHAR(80) NOT NULL UNIQUE,
  `site_name` VARCHAR(160) NOT NULL,
  `kabupaten` VARCHAR(100) NOT NULL,
  `kecamatan` VARCHAR(100) NULL,
  `latitude` DECIMAL(9,6) NOT NULL,
  `longitude` DECIMAL(9,6) NOT NULL,
  `depth_m` DECIMAL(5,1) NULL,
  `depth_source` VARCHAR(160) NULL,
  `shelter` ENUM('teluk','semi','terbuka') NOT NULL DEFAULT 'semi',
  `access_note` VARCHAR(255) NULL,
  `recommended_species` VARCHAR(255) NULL,
  `score_depth` INT NOT NULL DEFAULT 0,
  `score_shelter` INT NOT NULL DEFAULT 0,
  `score_access` INT NOT NULL DEFAULT 0,
  `score_conflict` INT NOT NULL DEFAULT 0,
  `suitability_score` INT NOT NULL DEFAULT 0,
  `suitability_class` ENUM('S1','S2','S3','N') NOT NULL DEFAULT 'S2',
  `constraints_note` TEXT NULL,
  `notes` TEXT NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `water_measurements` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `device_id` INT NOT NULL,
  `measured_at` DATETIME NOT NULL,
  `temp_sensor_c` DECIMAL(6,2) NULL,
  `sst_c` DECIMAL(6,2) NULL,
  `salinity_psu` DECIMAL(6,2) NULL,
  `ph` DECIMAL(5,2) NULL,
  `turbidity_ntu` DECIMAL(7,2) NULL,
  `depth_m` DECIMAL(6,2) NULL,
  `is_simulated` TINYINT(1) NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX `idx_water_measured` (`measured_at`),
  FOREIGN KEY (`device_id`) REFERENCES `devices`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `owc_measurements` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `device_id` INT NOT NULL,
  `measured_at` DATETIME NOT NULL,
  `power_w` DECIMAL(9,2) NOT NULL DEFAULT 0,
  `voltage_v` DECIMAL(7,2) NOT NULL DEFAULT 0,
  `current_a` DECIMAL(8,3) NOT NULL DEFAULT 0,
  `energy_wh` DECIMAL(10,2) NOT NULL DEFAULT 0,
  `battery_pct` DECIMAL(5,2) NULL,
  `is_simulated` TINYINT(1) NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX `idx_owc_measured` (`measured_at`),
  FOREIGN KEY (`device_id`) REFERENCES `devices`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `wave_measurements` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `device_id` INT NOT NULL,
  `measured_at` DATETIME NOT NULL,
  `wave_height_m` DECIMAL(6,3) NOT NULL DEFAULT 0,
  `wave_period_s` DECIMAL(6,2) NOT NULL DEFAULT 0,
  `wave_direction_deg` INT NULL,
  `wind_speed_ms` DECIMAL(6,2) NULL,
  `wind_direction_deg` INT NULL,
  `is_simulated` TINYINT(1) NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX `idx_wave_measured` (`measured_at`),
  FOREIGN KEY (`device_id`) REFERENCES `devices`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `fishcount_results` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `device_id` INT NULL,
  `image_path` VARCHAR(255) NULL,
  `media_type` ENUM('image','video') NOT NULL DEFAULT 'image',
  `media_duration_s` DECIMAL(8,2) NULL,
  `frames_analyzed` INT NULL,
  `thumb_path` VARCHAR(255) NULL,
  `detected_count` INT NULL,
  `avg_length_cm` DECIMAL(6,2) NULL,
  `biomass_kg` DECIMAL(9,2) NULL,
  `confidence_pct` DECIMAL(5,2) NULL,
  `processing_status` VARCHAR(32) NOT NULL DEFAULT 'pending',
  `status_message` VARCHAR(255) NULL,
  `is_simulated` TINYINT(1) NOT NULL DEFAULT 0,
  `is_manual` TINYINT(1) NOT NULL DEFAULT 0,
  `manual_count` INT NULL,
  `validated_by` INT NULL,
  `validated_at` DATETIME NULL,
  `notes` TEXT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `alerts` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `device_id` INT NULL,
  `parameter` VARCHAR(40) NOT NULL,
  `severity` ENUM('info','warning','critical') NOT NULL DEFAULT 'warning',
  `title` VARCHAR(160) NOT NULL,
  `message` TEXT NOT NULL,
  `actual_value` DECIMAL(10,3) NULL,
  `threshold_value` DECIMAL(10,3) NULL,
  `occurred_at` DATETIME NOT NULL,
  `status` ENUM('open','resolved') NOT NULL DEFAULT 'open',
  `resolved_by` INT NULL,
  `resolved_at` DATETIME NULL,
  `is_simulated` TINYINT(1) NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;




















