INSERT INTO `fish_species` (`id`, `name`, `latin_name`, `category`, `cycle_months_min`, `cycle_months_max`, `target_weight_kg`, `lw_a`, `lw_b`, `optimal_temp_min`, `optimal_temp_max`, `optimal_ph_min`, `optimal_ph_max`, `optimal_salinity_min`, `optimal_salinity_max`, `description`, `is_active`, `created_at`, `updated_at`) VALUES
('1', 'Kakap putih', 'Lates calcarifer', 'laut', '5', '8', '0.600', '0.01060', '3.050', '27.0', '32.0', '7.5', '8.5', '5.00', '35.00', 'Favorit KJA laut tropis. Tumbuh cepat, tahan salinitas berubah, harga stabil.', '1', '2026-11-14 20:29:36', '2026-11-14 20:29:36'),
('2', 'Kerapu cantang', 'Epinephelus fuscoguttatus × lanceolatus', 'laut', '8', '12', '0.700', '0.01120', '3.030', '26.0', '30.0', '7.8', '8.4', '28.00', '33.00', 'Komoditas ekspor premium (hidup/segar). Membutuhkan pakan rucah atau pelet khusus.', '1', '2026-11-14 20:29:36', '2026-11-14 20:29:36'),
('3', 'Bandeng', 'Chanos chanos', 'brackish', '4', '6', '0.350', '0.01210', '2.980', '26.0', '32.0', '7.5', '8.5', '10.00', '30.00', 'Populer di keramba teluk dangkal. Pemeliharaan relatif mudah dengan pakan alami + pelet.', '1', '2026-11-14 20:29:36', '2026-11-14 20:29:36'),
('4', 'Nila', 'Oreochromis niloticus', 'tawar', '3', '4', '0.500', '0.01500', '3.000', '26.0', '30.0', '6.5', '8.5', '0.00', '8.00', 'Primadona KJA waduk & danau. Pertumbuhan cepat dengan pelet berkualitas.', '1', '2026-11-14 20:29:36', '2026-11-14 20:29:36');
INSERT INTO `kja_sites` (`id`, `slug`, `site_name`, `kabupaten`, `kecamatan`, `latitude`, `longitude`, `depth_m`, `depth_source`, `shelter`, `access_note`, `recommended_species`, `score_depth`, `score_shelter`, `score_access`, `score_conflict`, `suitability_score`, `suitability_class`, `constraints_note`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES
('1', 'teluk-banten-barat', 'Teluk Banten Barat — depan Karangantu–Panisbang', 'Kab. Serang', 'Kramatwatu/Karangantu', '-5.985000', '106.155000', '8.0', 'GEBCO 2020 via OpenTopoData (probe langsung)', 'teluk', '±5–6 km dari PPI Karangantu; perahu dari pantai Karangantu/Kemaren', 'Kerapu macan, kerapu cantang, bandeng laut, kakap putih', '40', '25', '12', '18', '95', 'S1', 'Gelombang di mulut teluk naik saat musim barat — tetap jauh lebih terlindung dibanding pantai barat Banten.', 'Teluk tertutup dengan kedalaman 7–8 m di bagian tengah — tepat pada rentang ideal KJA laut (5–15 m). Telah menjadi zona KJA masyarakat untuk kerapu dan bandeng; studi kesesuaian budidaya kerapu menandai Teluk Banten sebagai kawasan sangat sesuai. Dekat PPI Karangantu memudahkan logistik benih, pakan, dan panen.', '1', '2026-11-14 20:25:46', NULL),
('2', 'teluk-banten-timur', 'Teluk Banten Timur — depan Bojonegara–Pulau Dua', 'Kab. Serang', 'Bojonegara/Pulosari', '-5.990000', '106.180000', '7.0', 'GEBCO 2020 via OpenTopoData (probe langsung)', 'teluk', '±2–3 km dari pantai Bojonegara/Jarai, dekat jalan raya utara Kab. Serang', 'Kerapu macan, kerapu cantang, kakap putih', '40', '25', '15', '14', '94', 'S1', '±3 km dari Suaka Margasatwa Pulau Dua (hutan mangrove) — jaga jarak dari zona mangrove dan rutin pantau kualitas air.', 'Bagian timur Teluk Banten dengan kedalaman ±7 m dan perairan terlindung. Akses darat paling mudah di antara titik Teluk Banten. Muara sungai di sekitar teluk membawa nutrien — sensor pH dan suhu BOLU cocok dipasang di zona ini untuk pemantauan rutin.', '1', '2026-11-14 20:25:46', NULL),
('3', 'teluk-lada', 'Teluk Lada — mulut teluk (depan Menewu–Sindangsari)', 'Kab. Pandeglang', 'Panimbang', '-6.503000', '105.775000', '15.0', 'GEBCO 2020 via OpenTopoData (probe langsung)', 'teluk', '±2–4 km dari jalan desa Menewu/Sindangsari; dermaga desa di pantai timur teluk', 'Kerapu cantang, kakap putih, bawal laut', '40', '25', '10', '18', '93', 'S1', 'Akses jalan desa lebih terbatas; gelombang di mulut teluk saat angin barat daya.', 'Teluk tertutup di barat daya Pandeglang yang terlindung dari gelombang Selat Sunda oleh ujung Tanjung Lesung. Kualitas perairannya sudah terkaji dalam publikasi riset perairan Teluk Lada. Kedalaman 12–15 m di mulut teluk — pas untuk KJA kerapu.', '1', '2026-11-14 20:25:46', NULL),
('4', 'panimbang-barat', 'Perairan Panimbang Barat', 'Kab. Pandeglang', 'Panimbang', '-6.490000', '105.730000', '9.0', 'GEBCO 2020 via OpenTopoData (probe langsung)', 'semi', '±3–5 km dari Pantai Panimbang & pelabuhan; perahu nelayan tersedia', 'Kerapu cantang, kerapu macan, kakap putih', '40', '15', '15', '18', '88', 'S2', 'Menghadap barat laut — gelombang naik saat musim barat; bukan teluk tertutup penuh.', 'Perairan di depan Kecamatan Panimbang yang sudah aktif berbudidaya KJA kerapu cantang. Kedalaman ±9 m ideal untuk jaring apung; ketersediaan benih, pakan, dan tenaga kerja budidaya setempat memudahkan operasional.', '1', '2026-11-14 20:25:46', NULL),
('5', 'teluk-menyawak-labuan', 'Teluk Menyawak — Labuan', 'Kab. Pandeglang', 'Labuan', '-6.360000', '105.815000', '10.0', 'GEBCO 2020 via OpenTopoData (probe langsung)', 'semi', '±2–3 km dari PPI Labuan & dermaga; jalan provinsi langsung', 'Kerapu macan, kakap putih, bandeng', '40', '15', '15', '16', '86', 'S2', 'Transit kapal/perahu Labuan–Umang; pilih area di belakang gugus Pulau Menyawak.', 'Studi tata ruang pesisir Pandeglang menandai perairan Teluk Kecamatan Labuan layak untuk budidaya kerangan dan keramba jaring apung. Kedalaman 10–14 m; kedekatan PPI Labuan memudahkan logistik ikan dan pakan.', '1', '2026-11-14 20:25:46', NULL),
('6', 'carita', 'Perairan Carita', 'Kab. Pandeglang', 'Carita', '-6.330000', '105.820000', '12.0', 'GEBCO 2020 via OpenTopoData (probe langsung)', 'semi', 'Di depan pantai wisata Carita; jalan raya Anyer–Panimbang', 'Kerapu macan, kakap putih', '40', '15', '15', '10', '80', 'S2', 'Tumpang tindih zona wisata bahari Carita — perlu koordinasi tata ruang perikanan–pariwisata.', 'Kedalaman 12–16 m pada 1–2 km dari pantai. Gelombang Selat Sunda moderat; area lebih tenang di sisi utara dekat gugus karang. Layak budidaya dengan catatan tata ruang wisata.', '1', '2026-11-14 20:25:46', NULL),
('7', 'pulau-tunda', 'Perairan Pulau Tunda', 'Kab. Serang', 'Wargasara', '-5.815000', '106.250000', '15.0', 'GEBCO 2020 via OpenTopoData (probe langsung)', 'semi', 'Akses perahu ±15 menit dari Desa Wargasara', 'Kerapu cantang, kerapu macan', '40', '15', '8', '16', '79', 'S2', 'Perairan lebih terbuka (sisi barat menghadap laut lepas); logistik via perahu dari Wargasara.', 'Analisis spasial menandai perairan Pulau Tunda berpotensi untuk budidaya kerapu (Epinephelus sp.) namun belum optimal karena minim informasi. Kedalaman 15–16 m di sisi barat daya pulau — batas atas rentang ideal; cocok untuk kerapu dengan sistem jangkar memadai.', '1', '2026-11-14 20:25:46', NULL),
('8', 'teluk-sumur', 'Teluk Sumur — buffer TN Ujung Kulon', 'Kab. Pandeglang', 'Sumur', '-6.650000', '105.570000', '5.0', 'GEBCO 2020 via OpenTopoData (probe langsung)', 'semi', 'Dekat Desa Sumur/Sumberjaya; jalan menuju TNUK', '— (perlu perizinan konservasi)', '40', '15', '12', '2', '69', 'S3', 'Berbatasan Taman Nasional Ujung Kulon — tata ruang konservasi membatasi budidaya; perlu izin & koordinasi pengelola TNUK.', 'Kedalaman ±5 m tepat di batas bawah ideal, namun kedekatan zona konservasi TNUK (Pulau Panaitan dan perairannya) menjadikan titik ini kurang cocok untuk KJA komersial tanpa proses perizinan panjang.', '1', '2026-11-14 20:25:46', NULL),
('9', 'anyer', 'Perairan Anyer', 'Kab. Serang', 'Anyer', '-6.085000', '105.875000', '30.0', 'GEBCO 2020 via OpenTopoData + survei batimetri Anyer (22–39 m)', 'terbuka', 'Di depan pantai wisata Anyer; akses sangat mudah', '— (tidak direkomendasikan)', '15', '8', '15', '5', '43', 'N', 'Jalur pelayaran feri Merak–Bakauheni & lalu lintas kapal Selat Sunda; zona wisata pantai; dasar perairan curam.', 'Lereng bawah laut Anyer menurun cepat: survei batimetri perairan Anyer mencatat 22–39 m dan GEBCO menunjukkan ±30 m hanya sekitar 1 km dari pantai. Kombinasi jalur kapal, zona wisata, dan kedalaman menjadikan titik ini tidak direkomendasikan untuk KJA.', '1', '2026-11-14 20:25:46', NULL);
